<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {api,post} from '../api'
import {usePolling} from '../usePolling'
import {direction,flag,number,percent,price,time} from '../format'
import type {Audit,Availability,Replay,Report,SignalEvaluation} from '../types'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import Pager from '../components/Pager.vue'
const report=ref<Report|null>(null); const availability=ref<Availability|null>(null); const replay=ref<Replay|null>(null); const audit=ref<Audit[]|null>(null)
const selected=ref<SignalEvaluation|null>(null);const search=ref('');const notifications=ref(false);const page=ref(0);const busy=ref(false);const actionError=ref('')
const inputTime=(milliseconds:number)=>new Date(milliseconds+8*3600_000).toISOString().slice(0,16)
const from=ref(inputTime(Date.now()-3600_000));const to=ref(inputTime(Date.now()));const symbol=ref('ARIAUSDT')
const {error}=usePolling(async signal=>{const [r,a]=await Promise.all([api<Report>('/api/evaluation',{signal}),api<Availability>('/api/replay/availability',{signal})]);report.value=r;availability.value=a},60000)
const complete=computed(()=>(report.value?.signals??[]).filter(e=>!e.signal.isNotification&&e.status===3))
const filtered=computed(()=>(report.value?.signals??[]).filter(e=>e.signal.symbol.toLowerCase().includes(search.value.trim().toLowerCase())&&(!notifications.value||e.signal.isNotification)).sort((a,b)=>Date.parse(b.signal.time)-Date.parse(a.signal.time)))
const paged=computed(()=>filtered.value.slice(page.value*20,(page.value+1)*20));watch([search,notifications],()=>{page.value=0})
const status=(s:number)=>['入口缺失','观察中','有缺口','完整'][s]??'Unknown'
const average=(field:'mfe'|'mae')=>complete.value.length?percent(complete.value.reduce((sum,e)=>sum+(e[field]??0),0)/complete.value.length):'Unknown'
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;actionError.value='';try{await work();availability.value=await api('/api/replay/availability')}catch(e){actionError.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
const refresh=()=>run(async()=>{report.value=await post<Report>('/api/evaluation/refresh')})
const runAudit=()=>run(async()=>{audit.value=await api<Audit[]>('/api/replay/audit?limit=100')})
const runReplay=()=>run(async()=>{replay.value=await post<Replay>('/api/replay',{from:new Date(from.value+':00+08:00').toISOString(),to:new Date(to.value+':00+08:00').toISOString(),symbol:symbol.value.trim().toUpperCase()})})
</script>
<template><PageIntro eyebrow="MEASURE THE SIGNAL" title="发现之后，市场怎样走？" description="保存当时的判断，等待完整结果；把证据与未知都留下。"><button class="replay-action" :disabled="busy" @click="refresh">{{busy?'处理中…':'更新评估'}}</button></PageIntro><p v-if="error||actionError" role="alert" class="radar-notice">{{actionError||error}}</p><p class="radar-notice">从信号后首个 5m 开盘观察随后 24h。未到期、入口缺失和历史缺口不会计为失败。这里衡量研究信号，不代表可成交收益。后台每小时更新。</p><div class="stats"><StatCard label="Episode 首次信号" :value="report?.signals.filter(e=>!e.signal.isNotification).length??0" foot="按 Episode 去重"/><StatCard label="完整 24h 样本" :value="complete.length" foot="288 根连续闭合 5m K 线"/><StatCard label="待完成 / 缺失" :value="report?.signals.filter(e=>e.status!==3).length??0" foot="继续等待，不以 0 填充"/><StatCard label="完整样本平均 MFE / MAE" :value="`${average('mfe')} / ${average('mae')}`" foot="方向性百分数 · 非负幅度"/></div><div class="section-heading"><h2>24h 信号追踪</h2><span class="refresh-text">{{time(report?.asOf)}} · {{report?.version}}</span></div><p v-if="report?.signalsTruncated" class="radar-notice">读取记录达到上限，Precision 与 Recall 百分比暂不计算。</p><div class="market-panel"><div class="toolbar"><label class="search"><input v-model="search" aria-label="搜索评估合约" placeholder="搜索合约"></label><label class="checkbox"><input v-model="notifications" type="checkbox">仅通知预留记录</label><span class="results">{{filtered.length}} 个结果</span></div><div class="table-scroll"><table><thead><tr><th>合约 / 来源</th><th>信号时间</th><th>方向</th><th>状态 / 覆盖</th><th>MFE</th><th>MAE</th><th>Hit20 / 50</th><th>Drop20 / 30</th><th>Lead · pp</th></tr></thead><tbody><tr v-for="e in paged" :key="e.signal.key" :title="e.reason" @click="selected=e"><td>{{e.signal.symbol}}<small>{{e.signal.isNotification?'通知预留':'首次信号'}}</small></td><td>{{time(e.signal.time)}}</td><td>{{direction(e.signal.direction)}}</td><td>{{status(e.status)}} · {{e.observedBars}}/{{e.expectedBars}}</td><td>{{percent(e.mfe)}}{{e.status===3?'':'*'}}</td><td>{{percent(e.mae)}}{{e.status===3?'':'*'}}</td><td>{{flag(e.hit20)}} / {{flag(e.hit50)}}</td><td>{{flag(e.drop20)}} / {{flag(e.drop30)}}</td><td>{{number(e.signal.direction===0?e.captureLead:e.crashLead)}}</td></tr><tr v-if="!filtered.length"><td colspan="9" class="empty">暂无符合条件的样本。Unknown 不代表 0% 准确率。</td></tr></tbody></table></div><Pager v-model="page" :total="filtered.length" :size="20">* 临时极值仅代表已观测区间，点击查看研究入口及策略版本。</Pager></div>
<section v-if="selected" class="detail"><div class="section-heading"><h2>{{selected.signal.symbol}} · 评估详情</h2><button class="text-button" @click="selected=null">收起 ×</button></div><div class="detail-grid"><div><span>信号时价格</span><strong>{{price(selected.signal.price)}}</strong></div><div><span>入口 · 下一 5m Open</span><strong>{{price(selected.entryPrice)}}</strong><small>{{time(selected.entryTime,true)}}</small></div><div><span>窗口结束</span><strong>{{time(selected.windowEnd)}}</strong></div><div><span>策略版本</span><strong>{{selected.signal.strategyVersion}}</strong></div><div><span>冻结 Lead 参考价</span><strong>{{price(selected.signal.referencePrice)}}</strong></div><div><span>CaptureLead / CrashLead · pp</span><strong>{{number(selected.captureLead)}} / {{number(selected.crashLead)}}</strong></div></div><p>{{selected.reason}}</p><p>{{selected.signal.key}}</p></section>
<div class="section-heading radar-heading"><h2>Precision@K 与极端行情召回</h2><span class="refresh-text">上海自然日 · 上下行分别统计</span></div><div class="market-panel table-scroll"><table><thead><tr><th>日期</th><th>方向</th><th>指标</th><th>分子 / 分母</th><th>结果</th><th>覆盖</th></tr></thead><tbody><tr v-for="p in report?.precision??[]" :key="`p:${p.date}:${p.direction}`"><td>{{p.date}}</td><td>{{direction(p.direction)}}</td><td>Precision@{{p.k}}</td><td>{{p.hits}} / {{p.selected}}</td><td>{{percent(p.percent)}}</td><td>成熟 {{p.completed}}/{{p.selected}}</td></tr><tr v-for="r in report?.recall??[]" :key="`r:${r.date}:${r.direction}`"><td>{{r.date}}</td><td>{{direction(r.direction)}}</td><td>ExtremeMoveRecall</td><td>{{r.capturedAssets}} / {{r.extremeAssets}}</td><td>{{percent(r.percent)}}</td><td>价格 {{r.coveredAssets}}/{{r.expectedAssets}} · 扫描{{r.scanCoverageComplete?'整日连续':'不足整日'}}</td></tr><tr v-if="!report?.precision.length&&!report?.recall.length"><td colspan="6" class="empty">尚无完整统计日期或通知样本。</td></tr></tbody></table></div>
<div class="section-heading radar-heading"><h2>按历史顺序回放</h2><span class="refresh-text">快照 {{availability?.frames??0}} 个 · 事件输入 {{availability?.eventInputs??0}} 个</span></div><p class="radar-notice">完整快照从 Phase 6 开始保存，默认保留 7 天。复用生产检测器、Episode 与通知策略，预算从空状态开始。不会用现在的行情填补历史，也不会发送 Windows 通知。</p><div class="market-panel"><div class="toolbar replay-controls"><label>开始 · 上海时间<input v-model="from" type="datetime-local" aria-label="回放开始时间"></label><label>结束 · 上海时间<input v-model="to" type="datetime-local" aria-label="回放结束时间"></label><label>跟踪合约<input v-model="symbol" aria-label="回放跟踪合约"></label><button class="replay-action" :disabled="busy" @click="runReplay">运行回放</button><button class="replay-action" :disabled="busy" @click="runAudit">复核历史事件</button></div><div class="table-footer"><span>可用范围：{{time(availability?.first)}} → {{time(availability?.last)}}；每次最多 6 小时 / 360 帧。全市场参与计算，仅跟踪所选合约。</span></div></div>
<template v-if="replay"><section class="detail"><h2>回放完成 · {{replay.frames}} 个快照 / {{replay.observations}} 个合约观测</h2><p>缺口 {{replay.gapCount}} · 新建 Episode {{replay.signals.filter(s=>!s.isNotification).length}} · 模拟通知 {{replay.simulatedNotifications.length}}</p><p>{{replay.note}}</p><p v-if="replay.coverage.length">每帧合约数 {{Math.min(...replay.coverage.map(c=>c.assets))}}～{{Math.max(...replay.coverage.map(c=>c.assets))}}；新鲜价格数 {{Math.min(...replay.coverage.map(c=>c.freshPrices))}}～{{Math.max(...replay.coverage.map(c=>c.freshPrices))}}。</p></section><div class="market-panel table-scroll"><table><thead><tr><th>时间</th><th>合约</th><th>价格</th><th>上涨评分 / 阶段</th><th>下跌评分 / 阶段</th><th>置信度</th><th>策略</th></tr></thead><tbody><tr v-for="p in replay.trace.slice(-100)" :key="`${p.time}:${p.assetId}`"><td>{{time(p.time)}}</td><td>{{p.symbol}}</td><td>{{price(p.price)}}</td><td>{{number(p.up.score,1)}} · {{p.up.stage}}</td><td>{{number(p.down.score,1)}} · {{p.down.stage}}</td><td>{{p.up.dataConfidence}} / {{p.down.dataConfidence}}</td><td>{{p.up.strategyVersion}}</td></tr><tr v-if="!replay.trace.length"><td colspan="7" class="empty">所选区间没有该合约的快照。</td></tr></tbody></table></div></template>
<template v-if="audit"><section class="detail"><h2>事件复核 · {{audit.length}} 条</h2><p>一致 {{audit.filter(a=>a.status==='Match').length}} · 差异 {{audit.filter(a=>a.status==='Mismatch').length}} · 无法复核 {{audit.filter(a=>!['Match','Mismatch'].includes(a.status)).length}}。事件复核不是连续行情回测。</p></section><div class="market-panel table-scroll"><table><thead><tr><th>时间</th><th>合约</th><th>原评分</th><th>复算评分</th><th>结果</th><th>说明 · 最近 20 条</th></tr></thead><tbody><tr v-for="a in audit.slice(0,20)" :key="a.eventId"><td>{{time(a.time)}}</td><td>{{a.symbol}}</td><td>{{number(a.savedScore,1)}}</td><td>{{number(a.replayedScore,1)}}</td><td>{{a.status}}</td><td class="decision-reason">{{a.reason}} · {{a.strategyVersion}}</td></tr></tbody></table></div></template><details class="detail"><summary>指标口径与限制</summary><p>{{report?.methodology}}</p><p>Hit20/50 为研究入口之后最大上涨 ≥20%/50%；Drop20/30 为最大下跌 ≥20%/30%。Lead 使用首次信号冻结的参考价，单位为百分点。Recall 仅覆盖整日扫描和价格历史充分的合约集合，不能冒充完整历史市场。</p><p>训练、验证和测试应按时间分开。当前没有自动调参或机器学习，也没有模拟费用、滑点和真实成交。</p></details></template>
